def make_task(
    id: int = 1,
    title: str = "Test task",
    status: TaskStatus = TaskStatus.PENDING,
    priority: TaskPriority = TaskPriority.MEDIUM,
    due_at=None,
    completed_at=None,
    created_at=None,
    tags=None,
) -> Task:
    return Task(
        id=id,
        title=title,
        status=status,
        priority=priority,
        due_at=due_at,
        completed_at=completed_at,
        created_at=created_at or FIXED_NOW,
        tags=tags or [],
    )

"""Tests for tasks_api.models — Task, Tag, TaskStatus, TaskPriority."""

from __future__ import annotations

from datetime import datetime, timezone, timedelta

import pytest

from tasks_api.models import Tag, Task, TaskPriority, TaskStatus


class TestTaskStatus:
    def test_values(self):
        assert TaskStatus.PENDING.value == "pending"
        assert TaskStatus.DONE.value == "done"

    def test_from_string(self):
        assert TaskStatus("pending") is TaskStatus.PENDING
        assert TaskStatus("done") is TaskStatus.DONE


class TestTaskPriority:
    def test_values(self):
        assert TaskPriority.LOW.value == "low"
        assert TaskPriority.MEDIUM.value == "medium"
        assert TaskPriority.HIGH.value == "high"

    def test_order_key_high_first(self):
        assert TaskPriority.order_key(TaskPriority.HIGH) < TaskPriority.order_key(TaskPriority.MEDIUM)
        assert TaskPriority.order_key(TaskPriority.MEDIUM) < TaskPriority.order_key(TaskPriority.LOW)


class TestTag:
    def test_normalizes_to_lowercase(self):
        assert Tag("Hello").name == "hello"

    def test_strips_whitespace(self):
        assert Tag("  foo  ").name == "foo"

    def test_allows_hyphens_and_underscores(self):
        assert Tag("my-tag_1").name == "my-tag_1"

    @pytest.mark.parametrize("bad_name", ["", "   ", "a b", "foo!", "x@y"])
    def test_rejects_invalid_names(self, bad_name):
        with pytest.raises(ValueError):
            Tag(bad_name)

    def test_rejects_too_long_name(self):
        with pytest.raises(ValueError, match="32 characters"):
            Tag("a" * 33)

    def test_rejects_non_string(self):
        with pytest.raises(TypeError):
            Tag(123)  # type: ignore[arg-type]


class TestTask:
    def test_defaults(self):
        task = Task(id=1, title="t")
        assert task.status == TaskStatus.PENDING
        assert task.priority == TaskPriority.MEDIUM
        assert task.due_at is None
        assert task.completed_at is None
        assert task.tags == []
        assert task.created_at.tzinfo is not None

    @pytest.mark.parametrize(
        "due_at, status, expected",
        [
            (None, TaskStatus.PENDING, False),
            # Due in the past but done → not overdue
            (
                datetime(2025, 1, 1, tzinfo=timezone.utc),
                TaskStatus.DONE,
                False,
            ),
            # Due in the past and pending → overdue
            (
                datetime(2025, 1, 1, tzinfo=timezone.utc),
                TaskStatus.PENDING,
                True,
            ),
            # Due in the future → not overdue
            (
                datetime(2099, 1, 1, tzinfo=timezone.utc),
                TaskStatus.PENDING,
                False,
            ),
        ],
    )
    def test_is_overdue(self, due_at, status, expected):
        now = datetime(2025, 6, 15, tzinfo=timezone.utc)
        task = Task(id=1, title="t", status=status, due_at=due_at)
        assert task.is_overdue(now) is expected

"""Tests for tasks_api.repository — InMemoryTaskRepository and normalize_tags."""

from __future__ import annotations

import pytest

from tasks_api.models import Tag, Task, TaskPriority, TaskStatus
from tasks_api.repository import InMemoryTaskRepository, normalize_tags
from tests.conftest import make_task


class TestInMemoryTaskRepository:
    @pytest.fixture
    def repo(self):
        return InMemoryTaskRepository()

    def test_next_id_increments(self, repo):
        assert repo.next_id() == 1
        assert repo.next_id() == 2

    def test_add_and_get(self, repo):
        task = make_task(id=1)
        repo.add(task)
        assert repo.get(1) is task

    def test_get_missing_returns_none(self, repo):
        assert repo.get(999) is None

    def test_add_duplicate_raises(self, repo):
        repo.add(make_task(id=1))
        with pytest.raises(ValueError, match="already exists"):
            repo.add(make_task(id=1))

    def test_list_returns_all(self, repo):
        repo.add(make_task(id=1))
        repo.add(make_task(id=2, title="Second"))
        items = list(repo.list())
        assert len(items) == 2

    def test_list_returns_snapshot(self, repo):
        repo.add(make_task(id=1))
        snapshot = repo.list()
        assert isinstance(snapshot, list)

    def test_update(self, repo):
        task = make_task(id=1, title="Original")
        repo.add(task)
        task.title = "Updated"
        repo.update(task)
        assert repo.get(1).title == "Updated"

    def test_update_missing_raises(self, repo):
        with pytest.raises(KeyError):
            repo.update(make_task(id=999))

    def test_delete_existing(self, repo):
        repo.add(make_task(id=1))
        assert repo.delete(1) is True
        assert repo.get(1) is None

    def test_delete_missing_returns_false(self, repo):
        assert repo.delete(999) is False


class TestNormalizeTags:
    def test_deduplicates(self):
        result = normalize_tags([Tag("foo"), Tag("FOO"), Tag("bar")])
        names = [t.name for t in result]
        assert names == ["foo", "bar"]

    def test_accepts_strings(self):
        result = normalize_tags(["Hello", "World"])
        assert all(isinstance(t, Tag) for t in result)
        assert result[0].name == "hello"

    def test_mixed_tag_and_string(self):
        result = normalize_tags([Tag("a"), "B", Tag("b")])
        assert len(result) == 2
        assert [t.name for t in result] == ["a", "b"]

    def test_empty_input(self):
        assert normalize_tags([]) == []
